form-time-picker.apiDescription:
## Models

Two-way bindings. Bind each one with the `v-model` syntax shown next to it — do not pass the prop and listen to its `update:` event separately.

```
export type GTimePickerModels = {
  /**
   * @description binding value, if it is an array, the length should be 2
   * @default ''
   */
  modelValue?: ModelValueType; // v-model="..."
}
```

## Props

```
export type GTimePickerProps = {
  /**
   * @description custom class name for TimePicker's dropdown
   * @default ''
   */
  popperClass?: string;
  /**
   * @description type of the picker
   * @default ''
   */
  type?: string;
  /**
   * @description whether to show clear button
   * @default true
   */
  clearable?: boolean;
  /**
   * @description Custom clear icon component
   * @default true
   */
  clearIcon?: string | boolean | Component;
  /**
   * @description whether the input is editable
   * @default true
   */
  editable?: boolean;
  /**
   * @description Custom prefix icon component
   * @default ''
   */
  prefixIcon?: IconString;
  /**
   * @description label in non-range mode
   * @default ''
   */
  label?: string;
  /**
   * @description label in non-range mode
   * @default ''
   */
  helpText?: string;
  /**
   * @description label in non-range mode
   * @default ''
   */
  messageError?: string;
  /**
   * @description [popper.js](https://popper.js.org/docs/v2/) parameters
   * @default {}
   */
  popperOptions?: Partial<Options>;
  /**
   * @description position of dropdown
   * @default 'bottom'
   */
  placement?: Placement;
  /**
   * @description range separator
   * @default '-'
   */
  rangeSeparator?: string;
  /**
   * @description an object array to set shortcut options
   * @default []
   */
  shortcuts?: unknown[];
  /**
   * @description input tabindex
   * @default 0
   */
  tabindex?: string | number;
  /**
   * @description whether to trigger form validation
   * @default true
   */
  validateEvent?: boolean;
  /**
   * @description list of possible positions for dropdown
   * @default ['bottom', 'top', 'right', 'left']
   */
  fallbackPlacements?: Placement[];
  /**
   * @description valor retornado al limpiar; para usar `undefined`, pasar `() => undefined`
   * @default undefined
   */
  valueOnClear?: string | number | boolean | Function;
  /**
   * @description whether to show the now button
   * @default true
   */
  showNow?: boolean;
  /** @description whether to pick time using arrow buttons */
  arrowControl?: boolean;
  /** @description unlink two date-panels in range-picker */
  unlinkPanels?: boolean;
  /** @description whether TimePicker is read only */
  readonly?: boolean;
  /** @description whether TimePicker is disabled */
  disabled?: boolean;
  /**
   * @description whether to pick a time range
   * @default false
   */
  isRange?: boolean;
  /** @description same as `id` in native input */
  id?: SingleOrRange<string>;
  /** @description same as `name` in native input */
  name?: SingleOrRange<string>;
  /** @description optional, default date of the calendar */
  defaultValue?: SingleOrRange<Date>;
  /** @description optional, the time value to use when selecting date range */
  defaultTime?: SingleOrRange<Date>;
  /** @description To specify the array of hours that cannot be selected */
  disabledHours?: GetDisabledHours;
  /** @description To specify the array of minutes that cannot be selected */
  disabledMinutes?: GetDisabledMinutes;
  /** @description To specify the array of seconds that cannot be selected */
  disabledSeconds?: GetDisabledSeconds;
  /** @description a function determining if a date is disabled with that date as its parameter. Should return a Boolean */
  disabledDate?: Function;
  /** @description set custom className */
  cellClassName?: Function;
  /** @description valores vacíos soportados por el componente */
  emptyValues?: unknown[];
  ariaLabel?: string;
  /** @description format of the displayed value in the input box */
  format?: string;
  /** @description optional, format of binding value. If not specified, the binding value will be a Date object */
  valueFormat?: string;
  /** @description optional, format of the date displayed value in TimePicker's dropdown */
  dateFormat?: string;
  /** @description optional, format of the time displayed value in TimePicker's dropdown */
  timeFormat?: string;
  /** @description placeholder for the start date in range mode */
  startPlaceholder?: string;
  /** @description placeholder for the end date in range mode */
  endPlaceholder?: string;
}
```

## Events

```
export type GTimePickerEvents = {
  "update:modelValue": any[];
}
```
